def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0
    # Each 3x3 motif is placed on a larger lattice; mark its local cell
    # matching the motif's lattice row and column.
    step = 5
    size = 4
    for ti, r0 in enumerate(range(0, h, step)):
        if r0 + size > h: break
        for tj, c0 in enumerate(range(0, w, step)):
            if c0 + size > w: break
            rr, cc = r0 + ti, c0 + tj
            if rr < r0 + size and cc < c0 + size and grid[rr][cc] == 2:
                out[rr][cc] = 8
    return out
